import org.jdom2.ProcessingInstruction;
import org.jdom2.Text;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for JDOMNodePointer.testNode
 */
public class JDOMNodePointer_testNode_TriageGen1Test {

    // Mocking NodePointer as it is not used in the logic but is a parameter
    private final NodePointer mockPointer = mock(NodePointer.class);

    @Test
    public void testNullTestReturnsTrue() {
        assertTrue(JDOMNodePointer.testNode(mockPointer, new Object(), null));
    }

    @Test
    public void testNodeNameTest_NotAnElement() {
        NodeNameTest test = mock(NodeNameTest.class);
        // node is not an Element
        assertFalse(JDOMNodePointer.testNode(mockPointer, new Object(), test));
    }

    @Test
    public void testNodeNameTest_WildcardNoPrefix() {
        Element element = new Element("any");
        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(true);
        when(test.getNodeName()).thenReturn(new QName(null, null, "any"));

        assertTrue(JDOMNodePointer.testNode(mockPointer, element, test));
    }

    @Test
    public void testNodeNameTest_WildcardWithPrefixMatch() {
        // Testing: if (wildcard || testName.getName().equals(...))
        Element element = new Element("local");
        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(true);
        when(test.getNodeName()).thenReturn(new QName("p", "local", "local"));
        when(test.getNamespaceURI()).thenReturn("http://uri");

        // Mocking the static-like behavior via real JDOM objects
        // Note: JDOMNodePointer.getNamespaceURI and getPrefix are called.
        // Since we can't easily mock static methods without PowerMock, 
        // we use real JDOM objects to satisfy the logic.
        element.setNamespace(new org.jdom2.Namespace("p", "http://uri"));

        assertTrue(JDOMNodePointer.testNode(mockPointer, element, test));
    }

    @Test
    public void testNodeNameTest_ExactMatch_NamespaceMatch() {
        Element element = new Element("local", new org.jdom2.Namespace("p", "http://uri"));
        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(false);
        when(test.getNodeName()).thenReturn(new QName("p", "local", "local"));
        when(test.getNamespaceURI()).thenReturn("http://uri");

        assertTrue(JDOMNodePointer.testNode(mockPointer, element, test));
    }

    @Test
    public void testNodeNameTest_ExactMatch_PrefixOnlyMatch() {
        // Testing: return equalStrings(namespaceURI, nodeNS) || nodeNS == null && equalStrings(testPrefix, getPrefix(node))
        Element element = new Element("local"); // no namespace, so nodeNS is null
        element.setPrefix("p");

        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(false);
        when(test.getNodeName()).thenReturn(new QName("p", "local", "local"));
        when(test.getNamespaceURI()).thenReturn(null);

        assertTrue(JDOMNodePointer.testNode(mockPointer, element, test));
    }

    @Test
    public void testNodeNameTest_Mismatch() {
        Element element = new Element("wrong");
        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(false);
        when(test.getNodeName()).thenReturn(new QName("p", "correct", "correct"));
        when(test.getNamespaceURI()).thenReturn("http://uri");

        assertFalse(JDOMNodePointer.testNode(mockPointer, element, test));
    }

    @Test
    public void testNodeTypeTest_Node() {
        NodeTypeTest test = mock(NodeTypeTest.class);
        when(test.getNodeType()).thenReturn(Compiler.NODE_TYPE_NODE);

        assertTrue(JDOMNodePointer.testNode(mockPointer, new Element("e"), test));
        assertTrue(JDOMNodePointer.testNode(mockPointer, new Document(new Element("e")), test));
        assertFalse(JDOMNodePointer.testNode(mockPointer, new Text("t"), test));
    }

    @Test
    public void testNodeTypeTest_Text() {
        NodeTypeTest test = mock(NodeTypeTest.class);
        when(test.getNodeType()).thenReturn(Compiler.NODE_TYPE_TEXT);

        assertTrue(JDOMNodePointer.testNode(mockPointer, new Text("t"), test));
        assertTrue(JDOMNodePointer.testNode(mockPointer, new CDATA("c"), test));
        assertFalse(JDOMNodePointer.testNode(mockPointer, new Element("e"), test));
    }

    @Test
    public void testNodeTypeTest_Comment() {
        NodeTypeTest test = mock(NodeTypeTest.class);
        when(test.getNodeType()).thenReturn(Compiler.NODE_TYPE_COMMENT);

        assertTrue(JDOMNodePointer.testNode(mockPointer, new Comment("c"), test));
        assertFalse(JDOMNodePointer.testNode(mockPointer, new Element("e"), test));
    }

    @Test
    public void testNodeTypeTest_PI() {
        NodeTypeTest test = mock(NodeTypeTest.class);
        when(test.getNodeType()).thenReturn(Compiler.NODE_TYPE_PI);

        assertTrue(JDOMNodePointer.testNode(mockPointer, new ProcessingInstruction("target", "data"), test));
        assertFalse(JDOMNodePointer.testNode(mockPointer, new Element("e"), test));
    }

    @Test
    public void testNodeTypeTest_UnknownType() {
        NodeTypeTest test = mock(NodeTypeTest.class);
        when(test.getNodeType()).thenReturn(999); // Invalid type code

        assertFalse(JDOMNodePointer.testNode(mockPointer, new Element("e"), test));
    }

    @Test
    public void testProcessingInstructionTest_Match() {
        ProcessingInstruction pi = new ProcessingInstruction("target", "data");
        ProcessingInstructionTest test = mock(ProcessingInstructionTest.class);
        when(test.getTarget()).thenReturn("target");

        assertTrue(JDOMNodePointer.testNode(mockPointer, pi, test));
    }

    @Test
    public void testProcessingInstructionTest_Mismatch() {
        ProcessingInstruction pi = new ProcessingInstruction("target", "data");
        ProcessingInstructionTest test = mock(ProcessingInstructionTest.class);
        when(test.getTarget()).thenReturn("different");

        assertFalse(JDOMNodePointer.testNode(mockPointer, pi, test));
    }

    @Test
    public void testProcessingInstructionTest_WrongNodeType() {
        Element element = new Element("e");
        ProcessingInstructionTest test = mock(ProcessingInstructionTest.class);

        // The logic is: if (test instanceof PI && node instanceof PI)
        // If node is not PI, it falls through to the final return false.
        assertFalse(JDOMNodePointer.testNode(mockPointer, element, test));
    }

    @Test
    public void testUnknownTestType() {
        NodeTest unknownTest = mock(NodeTest.class);
        assertFalse(JDOMNodePointer.testNode(mockPointer, new Element("e"), unknownTest));
    }
}
